#!/bin/bash
name="World"
echo "Hello, ${name}!"

count_errors() {
  local logfile="$1"
  grep -c 'ERROR' "$logfile" 2>/dev/null || echo 0
}
total=$(count_errors server.log)
echo "Found $total errors"

verbose=0
output=""
while getopts vf:o: opt; do
  case $opt in
    v) verbose=1 ;;
    f) output="$OPTARG" ;;
    o) output="$OPTARG" ;;
    *) echo "Usage: $0 [-v] [-f file]"; exit 1 ;;
  esac
done

